import sys,json,html,math
from pathlib import Path
ROOT=Path(__file__).parent
sys.path.insert(0,str(ROOT.parent/'potencias-centrales/.libs'))
from shapely.geometry import shape,Polygon,LineString,Point,box,mapping
from shapely.ops import unary_union
from shapely import make_valid
from pyproj import Transformer
D={y:json.loads((ROOT/f'datos/world_{y}.geojson').read_text(encoding='utf-8')) for y in [1600,1938,1994]}
def clean(g):return make_valid(g).buffer(0)
def get(y,*names):return clean(unary_union([clean(shape(f['geometry'])) for f in D[y]['features'] if f.get('geometry') and f['properties'].get('NAME') in names]))
land=clean(unary_union([clean(shape(f['geometry'])) for f in D[1600]['features'] if f.get('geometry')]))
COL={'hisp':'#9e4253','port':'#3f827e','burg':'#87627e','aust':'#be9650','bohem':'#d0ad6b','royal':'#ddc395','imperial':'#dfd8b9','escolon':'#c9868f','ptcolon':'#8eb9b0','frontier':'#ead7cb','other':'#dedbd0'}
regions=[]
def add(name,g,cat,note,unified=False,approx=False):
 g=clean(g)
 if g.is_empty:return
 regions.append(dict(name=name,g=g,cat=cat,color=COL[cat],note=note,unified=unified,approx=approx))
# Agrupación de la base: los pueblos y Estados ajenos no son territorios vacíos.
groups={}
for f in D[1600]['features']:
 if not f.get('geometry'):continue
 n=f['properties'].get('NAME') or 'Otros territorios y sociedades'
 if n=='Inca Empire':n='Región andina · etiqueta anacrónica de la base corregida'
 groups.setdefault(n,[]).append(clean(shape(f['geometry'])))
for n,gs in groups.items():
 g=clean(unary_union(gs));cat='imperial' if n=='Holy Roman Empire' else 'other'
 add(n,g,cat,'Estado, territorio o sociedad de referencia. La ausencia de color dinástico no implica ausencia de población ni de organización política.' if cat=='other' else 'Estados del Sacro Imperio: relación institucional con el emperador, con gobiernos propios. No son posesiones directas de la monarquía unificada.')
add('Coronas hispánicas peninsulares',get(1600,'Spain'),'hisp','Castilla, Aragón y Navarra bajo el mismo soberano. Las instituciones territoriales se conservan dentro de una estructura común.',True)
add('Reino de Portugal',get(1600,'Portugal'),'port','Portugal se incorpora desde 1580; el escenario hace permanente su integración política y sucesoria, conservando sus leyes y su red ultramarina.',True)
for n,es in [('Milan','Ducado de Milán'),('Naples','Reino de Nápoles'),('Sicily','Reino de Sicilia'),('Sardinia','Reino de Cerdeña')]:add(es,get(1600,n),'hisp','Posesión de la rama hispánica incorporada a la monarquía común. No se anexiona el resto de Italia.',True)
add('Países Bajos reunificados',get(1600,'Habsburg Netherlands','Dutch Republic'),'burg','Hipótesis adicional: un acuerdo fiscal y religioso evita la separación permanente de las provincias septentrionales. No es una consecuencia automática de la sucesión común.',True)
hre=get(1600,'Holy Roman Empire')
aut=unary_union([get(1994,'Austria','Slovenia'),land.intersection(Polygon([(10.3,46),(12.3,46),(12.4,47.1),(10.2,47.2)]))]).intersection(hre)
add('Tierras hereditarias austríacas',aut,'aust','Austria, Tirol y tierras alpinas y eslovenas de los Habsburgo: unidas a la sucesión hispánica. Guía posterior para algunas subdivisiones; contorno aproximado.',True,True)
cz=get(1938,'Czechoslovakia').intersection(box(11,48,19,52))
# La base checoslovaca de 1938 es incompleta tras Múnich: completar Bohemia con 1994.
cz=unary_union([cz,get(1994,'Czech Republic','Czechia')]).intersection(land).difference(get(1994,'Slovakia'))
silesia=land.intersection(Polygon([(14.6,50.8),(16,51.9),(18.5,51.2),(18.8,49.9),(17,49.6),(15.5,50.5)])).intersection(hre)
lusatia=hre.intersection(box(13.8,50.8,15.2,52.05))
bohem=unary_union([cz,silesia,lusatia]).intersection(hre)
add('Corona de Bohemia',bohem,'bohem','Bohemia, Moravia, Silesia y Lusacias se vinculan a la sucesión común mediante un acuerdo con sus estamentos. Geometría generalizada; no fronteras provinciales exactas.',True,True)
royal=unary_union([get(1994,'Slovakia'),land.intersection(Polygon([(16,45.3),(17.2,45.2),(17.3,46.8),(17,48),(16,48.5)]))]).difference(get(1600,'Ottoman Empire')).difference(aut).difference(bohem)
add('Hungría Real y Croacia habsbúrgica',royal,'royal','Solo la parte bajo autoridad habsbúrgica. No se incorporan la Hungría otomana ni Transilvania. Frontera militar simplificada.',True,True)
franche=land.intersection(Polygon([(5.25,46.3),(6.4,46.4),(7,47.5),(6.55,48.1),(5.6,47.7)]))
add('Franco Condado',franche,'burg','Herencia borgoñona, conservada junto con los Países Bajos. No equivale al Ducado de Borgoña francés. Contorno aproximado.',True,True)
# No se colorea todo el antiguo imperio inca como dominio efectivo en 1600.
newspain=get(1600,'Viceroyalty of New Spain')
add('Nueva España y Tierra Firme · ámbito colonial',newspain,'escolon','Área colonial generalizada de la base de 1600. El control variaba mucho y coexistía con comunidades indígenas autónomas; no representa ocupación homogénea.',True,True)
add('Antillas hispánicas',get(1600,'Cuba (Spain)','Hispaniola (Spain)'),'escolon','Islas y núcleos coloniales españoles. La base agrupa varias islas; no se atribuyen automáticamente todas las Antillas a la monarquía.',True)
andes=LineString([(-76,3),(-78,-1),(-77,-7),(-75,-12),(-72,-16),(-68,-17),(-66,-20),(-65,-24)]).buffer(1.3)
coast=LineString([(-80,0),(-79,-6),(-77,-12),(-74,-17),(-71,-22),(-70,-29),(-71,-35.8)]).buffer(.85)
add('Virreinato del Perú · núcleos y corredores',land.intersection(unary_union([andes,coast])),'escolon','Esquema de núcleos costeros y andinos, incluidos los ejes mineros. No expresa toda la extensión jurídica del virreinato ni dominio continuo en la Amazonia.',True,True)
north=land.intersection(LineString([(-77,7),(-74,5),(-71,8),(-67,10),(-64,10)]).buffer(1.1))
add('Nueva Granada y Venezuela · núcleos coloniales',north,'escolon','Corredores y asentamientos esquematizados. No se colorea el interior continental como territorio plenamente controlado.',True,True)
rio=land.intersection(LineString([(-57,-25.3),(-60,-31.5),(-58.4,-34.6)]).buffer(.65))
add('Paraguay y Río de la Plata · asentamientos',rio,'escolon','Representación de ejes de asentamiento hacia Asunción y Buenos Aires, no de los Estados modernos completos.',True,True)
brline=LineString([(-35.2,-5.8),(-34.9,-8.1),(-38.5,-13),(-39.1,-16.5),(-40.3,-20.3),(-43.2,-22.9),(-46.3,-24)])
add('Brasil portugués · franja de implantación',land.intersection(brline.buffer(.9)),'ptcolon','Núcleos y franjas costeras de implantación colonial hacia 1600. El Brasil moderno, el Amazonas y el interior no se consideran territorio portugués efectivamente ocupado.',True,True)
phil=land.intersection(unary_union([box(119,12,123,19),box(121,9,125.8,13.5)]))
add('Filipinas · área de implantación hispánica',phil,'escolon','Luzón y parte de las Bisayas, generalizadas. No se atribuye el control de todo Mindanao ni del archipiélago completo.',True,True)
frontiers=[('Frontera septentrional novohispana',land.intersection(Polygon([(-110,22),(-106,28),(-103,32),(-100,30),(-97,25),(-99,22)])),'Expansión, misiones y reclamaciones: control discontinuo; no una provincia moderna delimitada.'),('Perú · horizonte jurisdiccional interior',land.intersection(Polygon([(-79,2),(-72,1),(-64,-8),(-61,-20),(-66,-28),(-71,-31),(-76,-14)])),'Reclamaciones y jurisdicción nominal más amplias que la ocupación efectiva; pueblos autónomos y fronteras abiertas.'),('Brasil · hinterland reclamado',land.intersection(brline.buffer(3.5)),'Hinterland de las capitanías, muy esquemático: no implica control portugués efectivo ni un límite administrativo preciso.')]
ports=[
 ('Sevilla',-5.99,37.39,'hisp','Centro de la Carrera de Indias; el sistema portuario no se reduce a una sola ciudad.'),('Lisboa',-9.14,38.72,'port','Articulación atlántica y del Estado da Índia.'),('Amberes',4.4,51.22,'burg','En este escenario conserva su papel dentro de unos Países Bajos políticamente reunificados.'),('Viena',16.37,48.21,'aust','Centro dinástico y de la frontera danubiana.'),('Praga',14.42,50.08,'bohem','Centro de la Corona de Bohemia.'),('Milán',9.19,45.46,'hisp','Posesión italiana de la monarquía y articulación terrestre.'),('Génova',8.94,44.4,'trade','República independiente: colaboración financiera y logística; no dominio habsbúrgico.'),('Ceuta',-5.32,35.89,'port','Plaza portuguesa dentro de la monarquía común.'),('Tánger',-5.81,35.78,'port','Plaza portuguesa hacia 1600.'),('Mazagán',-8.5,33.25,'port','Enclave portugués, sin atribuir el interior de Marruecos.'),('Orán',-.64,35.7,'hisp','Plaza hispánica norteafricana, sin dominio general de Argelia.'),('Melilla',-2.94,35.29,'hisp','Plaza hispánica; el símbolo no implica control de su hinterland.'),('Azores',-25.7,37.8,'port','Archipiélago portugués; marcador de localización.'),('Madeira',-16.9,32.7,'port','Archipiélago portugués.'),('Canarias',-15.5,28.1,'hisp','Archipiélago de la Corona de Castilla.'),('Cabo Verde',-23.5,15,'port','Archipiélago y escala portuguesa.'),('São Tomé',6.7,.3,'port','Isla colonial portuguesa.'),('Elmina',-1.35,5.08,'port','Fortaleza y factoría portuguesa; no control de la actual Ghana.'),('Luanda',13.23,-8.84,'port','Núcleo fundado en 1576; control local, no la Angola moderna.'),('Mozambique',40.73,-15.03,'port','Isla y fortaleza: articulación marítima, no control de todo Mozambique.'),('Sofala',34.73,-20.18,'port','Factoría y fortificación portuguesa; dominio costero limitado.'),('Ormuz',56.45,27.06,'port','Enclave estratégico portugués; no soberanía sobre Persia.'),('Mascate',58.4,23.6,'port','Posición portuguesa en una red de puertos, sin control general de Arabia.'),('Goa',73.83,15.5,'port','Centro administrativo del Estado da Índia.'),('Diu',70.98,20.71,'port','Plaza fortificada portuguesa.'),('Cochín',76.27,9.97,'port','Presencia portuguesa condicionada por relaciones con poderes locales.'),('Colombo',79.86,6.93,'port','Implantación portuguesa en parte de la costa de Ceilán; el reino de Kandy sigue fuera.'),('Malaca',102.25,2.2,'port','Puerto bajo control portugués desde 1511; no la península malaya completa.'),('Macao',113.55,22.2,'concession','Asentamiento portugués autorizado bajo soberanía china, no anexión de China.'),('Nagasaki',129.87,32.75,'trade','Relación comercial portuguesa hacia 1600. Puerto japonés; no posesión territorial.'),('Ternate / Tidore',127.38,.75,'trade','Área de rivalidad, alianzas y comercio de especias; no control ibérico uniforme de las Molucas.'),('Manila',120.98,14.6,'hisp','Centro de la implantación española en Filipinas.'),('Cebú',123.89,10.32,'hisp','Núcleo español del archipiélago filipino.'),('Acapulco',-99.9,16.86,'hisp','Extremo americano del galeón de Manila.'),('Veracruz',-96.14,19.18,'hisp','Puerto atlántico novohispano.'),('La Habana',-82.37,23.11,'hisp','Articulación de las flotas del Caribe.'),('Cartagena',-75.48,10.39,'hisp','Puerto fortificado del Caribe.'),('Portobelo',-79.65,9.55,'hisp','Puerto de enlace con el istmo desde 1597.'),('Callao / Lima',-77.15,-12.06,'hisp','Núcleo del virreinato peruano y de sus conexiones del Pacífico.'),('Potosí',-65.75,-19.57,'hisp','Centro minero interior; no puerto.'),('Salvador',-38.5,-12.97,'port','Centro colonial portugués en Brasil.'),('Recife / Olinda',-34.87,-8.05,'port','Núcleo azucarero de la costa brasileña.'),('Río de Janeiro',-43.2,-22.9,'port','Asentamiento portugués atlántico.'),('Buenos Aires',-58.38,-34.6,'hisp','Asentamiento refundado en 1580; control regional limitado.')]
routes=[('Carrera de Indias',[(-6,36),(-18,27),(-40,18),(-61,15),(-75,20),(-82,23)],'hisp'),('Brasil atlántico',[(-9,38),(-22,20),(-30,0),(-38,-13)],'port'),('Ruta del Cabo',[(-9,38),(-25,15),(-29,-8),(-15,-28),(8,-36),(24,-37),(40,-20),(48,-2),(64,8),(74,15)],'port'),('Estado da Índia',[(74,15),(79,5),(90,3),(102,2),(110,10),(114,22)],'port'),('Comercio con Japón',[(114,22),(123,27),(130,33)],'port'),('Acapulco → Manila',[(-100,17),(-125,13),(-155,12),(-180,12)],'hisp'),('Acapulco → Manila · continuación',[(180,12),(155,12),(135,12),(121,15)],'hisp'),('Manila → Acapulco',[(121,15),(136,30),(157,37),(180,39)],'hisp'),('Manila → Acapulco · continuación',[(-180,39),(-155,38),(-130,33),(-115,25),(-100,17)],'hisp'),('Pacífico americano',[(-79,9),(-82,-3),(-77,-12),(-73,-25)],'hisp')]
sources=[('Abdicación y reparto de 1555–1556 · documentos históricos','https://germanhistorydocs.org/en/from-the-reformations-to-the-thirty-years-war-1500-1648/the-abdication-of-emperor-charles-v-1555-56'),('Fernando y los dominios austríacos, Bohemia y Hungría · Welt der Habsburger','https://www.habsburger.net/en/chapter/birth-austrian-line-ferdinand-i'),('El carácter electivo de la dignidad imperial · Welt der Habsburger','https://www.habsburger.net/en/glossary/holy-roman-empire'),('Unión portuguesa de 1580 · Museo del Ejército','https://ejercito.defensa.gob.es/museo/HECHOS_HISTORICOS/HECHOS_HISTORICOS/08.25_BATALLA_DE_ALCANTARA.html'),('Abjuración de Felipe II en los Países Bajos · Nationaal Archief','https://www.nationaalarchief.nl/beleven/onderwijs/bronnenbox/plakkaat-van-verlatinge-1581'),('Red portuguesa de puertos · Smithsonian','https://asia.si.edu/whats-on/exhibitions/encompassing-the-globe-portugal-and-the-world-in-the-16th-and-17th-centuries/'),('Cronología del comercio y del Brasil costero · Metropolitan Museum','https://www.metmuseum.org/exhibitions/listings/2013/interwoven-globe'),('Galeón de Manila · Metropolitan Museum','https://www.metmuseum.org/es/essays/the-manila-galleon-trade-1565-1815'),('Cartografía original y licencia · Historical Basemaps','https://github.com/aourednik/historical-basemaps')]
def esc(s):return html.escape(str(s),quote=True)
def txt(x,y,t,size=16,cls='',anchor='start'):return f'<text x="{x:.1f}" y="{y:.1f}" font-size="{size}" class="{cls}" text-anchor="{anchor}">{esc(t)}</text>'
def render(globalview):
 W,H=(1900,1300) if globalview else (1600,1300)
 mapbox=(24,130,W-48,870 if globalview else 890)
 clipgeom=box(-180,-59,180,83) if globalview else box(-13,31,37,62)
 proj=Transformer.from_crs('EPSG:4326','+proj=eqearth +lon_0=0 +datum=WGS84' if globalview else '+proj=lcc +lat_1=35 +lat_2=60 +lat_0=48 +lon_0=10 +datum=WGS84',always_xy=True).transform
 def xy(lon,lat):
  x,y=proj(lon,lat);return ((950+x/18700,540-y/18700) if globalview else (800+x/3350,535-y/3350))
 def path(g):
  if g.geom_type=='Polygon':return ' '.join('M'+' L'.join(f'{x:.1f},{y:.1f}' for x,y in [xy(*p[:2]) for p in ring.coords])+' Z' for ring in [g.exterior,*g.interiors])
  return ' '.join(path(q) for q in g.geoms) if hasattr(g,'geoms') else ''
 title='Una monarquía entre cuatro continentes' if globalview else 'La herencia de Carlos, reunida en Europa'
 sub='1600 alternativo · Coronas ibéricas y habsbúrgicas bajo una sucesión común · Territorios, enclaves y conexiones' if globalview else '1600 alternativo · Unión Ibérica incluida · Una monarquía común con reinos y leyes propios'
 x0,y0,mw,mh=mapbox
 s=[f'<svg xmlns="http://www.w3.org/2000/svg" width="{W}" height="{H}" viewBox="0 0 {W} {H}"><defs><clipPath id="mapclip"><rect x="{x0}" y="{y0}" width="{mw}" height="{mh}" rx="8"/></clipPath><pattern id="frontier" width="9" height="9" patternUnits="userSpaceOnUse" patternTransform="rotate(35)"><path d="M0 0V9" stroke="#b1856e" stroke-width="2"/></pattern></defs><style>text{{font-family:Segoe UI,Arial,sans-serif;fill:#303b3b}}.label{{font-weight:600;paint-order:stroke;stroke:#f8f3e6;stroke-width:3px;stroke-linejoin:round;pointer-events:none}}.small{{fill:#64716d}}.country,.port{{cursor:pointer}}.country:hover,.country:focus{{filter:brightness(1.15);stroke:#623542;stroke-width:2;outline:none}}.port:hover,.port:focus{{stroke:#111;stroke-width:2;outline:none}}.uniform .unified{{fill:#9e4253!important}}</style><rect width="{W}" height="{H}" fill="#f6f1e6"/>',txt(48,42,'ATLAS DE HISTORIAS POSIBLES · 03 · VISTA '+('MUNDIAL' if globalview else 'EUROPEA'),13,'small'),txt(48,84,title,39),txt(48,112,sub,15,'small'),f'<g clip-path="url(#mapclip)"><rect x="{x0}" y="{y0}" width="{mw}" height="{mh}" fill="#e1ebea"/>']
 for lat in range(-40,81,20) if globalview else range(30,71,10):
  pts=[xy(lon,lat) for lon in range(-180,181,2) if globalview or -20<=lon<=45];s.append('<path d="M'+' L'.join(f'{x:.1f},{y:.1f}' for x,y in pts)+'" fill="none" stroke="#cddcda"/>')
 for lon in range(-180,181,30) if globalview else range(-10,41,10):
  pts=[xy(lon,lat) for lat in range(-60,84,2) if globalview or 28<=lat<=65];s.append('<path d="M'+' L'.join(f'{x:.1f},{y:.1f}' for x,y in pts)+'" fill="none" stroke="#cddcda"/>')
 # Fronteras de los Estados de referencia sin colores que sugieran dominio europeo del mundo.
 for i,r in enumerate(regions):
  if not r['g'].intersects(clipgeom):continue
  if not globalview and r['cat'] in ['escolon','ptcolon']:continue
  g=r['g'].intersection(clipgeom);d=path(g);cl='country'+(' unified' if r['unified'] else '')
  dash='stroke-dasharray="4 2"' if r['approx'] else ''
  s.append(f'<path class="{cl}" data-type="region" data-i="{i}" tabindex="0" role="button" aria-label="{esc(r["name"])}" d="{d}" fill="{r["color"]}" fill-rule="evenodd" stroke="#f8f4e9" stroke-width="{.6 if globalview else 1}" {dash}><title>{esc(r["name"])}</title></path>')
 if globalview:
  colonial=unary_union([r['g'] for r in regions if r['cat'] in ['escolon','ptcolon']])
  for name,g,note in frontiers:
   g=g.difference(colonial)
   s.append(f'<path class="frontier-layer" d="{path(g.intersection(clipgeom))}" fill="url(#frontier)" opacity=".55" pointer-events="none"><title>{esc(name+" · "+note)}</title></path>')
  for name,coords,cat in routes:
   pts=[xy(*p) for p in coords];d='M'+' L'.join(f'{x:.1f},{y:.1f}' for x,y in pts)
   s.append(f'<g class="route-layer"><path d="{d}" fill="none" stroke="{COL[cat]}" stroke-width="17" opacity=".065"/><path d="{d}" fill="none" stroke="{COL[cat]}" stroke-width="1.8" stroke-dasharray="6 5" opacity=".8"><title>{esc(name)} · itinerario esquemático, no dominio del océano</title></path></g>')
 else:
  imperial=unary_union([hre,get(1600,'Milan','Savoy','Florence','Genoa','Habsburg Netherlands','Dutch Republic'),bohem,aut]).intersection(clipgeom)
  s.append(f'<path d="{path(imperial)}" fill="none" stroke="#998354" stroke-width="2.2" stroke-dasharray="7 5" pointer-events="none"><title>Contorno imperial generalizado: relación institucional, no posesión del soberano.</title></path>')
 for i,(name,lon,lat,cat,note) in enumerate(ports):
  if not clipgeom.covers(Point(lon,lat)):continue
  if not globalview and name not in ['Sevilla','Lisboa','Amberes','Viena','Praga','Milán','Génova','Ceuta','Tánger','Mazagán','Orán','Melilla']:continue
  x,y=xy(lon,lat);fill=COL.get(cat,'#faf7ed');radius=4 if globalview else 4.8
  s.append(f'<circle class="port" data-type="port" data-i="{i}" tabindex="0" role="button" aria-label="{esc(name)}" cx="{x:.1f}" cy="{y:.1f}" r="{radius}" fill="{fill}" stroke="#344a48" stroke-width="1.1"><title>{esc(name+" · "+note)}</title></circle>')
 if globalview:
  labels=[('EUROPA',15,58,20),('Nueva España',-106,17,18),('Antillas',-70,25,17),('Perú y Andes',-81,-13,18),('Brasil costero',-30,-16,18),('ÁFRICA',18,17,22),('ASIA',90,48,22),('China Ming',111,35,18),('Imperio mogol',78,25,17),('AUSTRALIA',135,-25,19),('Pueblos y Estados',-50,-4,13),('del interior americano',-50,-8,13)]
  plabels=[('Lisboa',-9,39,-40,-10),('Goa',74,15,14,-9),('Malaca',102,2,12,18),('Macao',114,22,-5,-14),('Nagasaki',130,33,14,-7),('Manila',121,15,20,8),('Acapulco',-100,17,-17,24),('Luanda',13,-9,15,16),('Mozambique',41,-15,14,15),('Ormuz',56,27,-17,-13),('Cabo Verde',-24,15,-70,-12),('Salvador',-38,-13,-22,24)]
 else:
  labels=[('CORONAS HISPÁNICAS',-2,40,21),('PORTUGAL',-8.2,40,16),('FRANCIA',2,47,23),('PAÍSES BAJOS',2.3,53.7,16),('SACRO IMPERIO',11,53,22),('Estados con gobierno propio',11,52.1,13),('BOHEMIA',15.5,50,18),('TIERRAS AUSTRÍACAS',12.7,46.9,15),('Hungría Real',19.4,48.6,16),('Croacia*',17.5,45.8,13),('HUNGRÍA OTOMANA',20.8,46.6,14),('TRANSILVANIA',24,47,15),('MILÁN',9.1,45.7,15),('NÁPOLES',16.2,40.9,16),('SICILIA',14,37.2,16),('CERDEÑA',8.5,39.3,14),('VENECIA',13.4,45.1,14),('ESTADOS PONTIFICIOS',13.2,43,12),('SUIZA',7.8,47.1,14),('FRANCO CONDADO*',4.8,47.9,13),('INGLATERRA',-1,54,18),('ESCOCIA',-4,58,16),('POLONIA-LITUANIA',26,53,20),('IMPERIO OTOMANO',29,40,21),('SABOYA',6.6,45.5,12)]
  plabels=[('Lisboa',-9.14,38.72,-55,2),('Sevilla',-5.99,37.39,-18,23),('Amberes',4.4,51.22,-60,-10),('Viena',16.37,48.21,8,20),('Praga',14.42,50.08,-16,-16),('Génova',8.94,44.4,-8,24)]
 for name,lon,lat,size in labels:
  x,y=xy(lon,lat);s.append(txt(x,y,name,size,'label','middle'))
 for name,lon,lat,dx,dy in plabels:
  x,y=xy(lon,lat);s.append(txt(x+dx,y+dy,name,13,'label'))
 # Leyenda integrada en el espacio atlántico / del Pacífico, sin cubrir los dominios.
 lx,ly,lw,lh=(48,743,470,235) if globalview else (47,150,430,244)
 s+=[f'<rect x="{lx}" y="{ly}" width="{lw}" height="{lh}" rx="8" fill="#fcf8ee" opacity=".97"/>',txt(lx+19,ly+29,'UNA MONARQUÍA · DISTINTAS CORONAS',16)]
 legend=[('hisp','Coronas hispánicas y posesiones italianas'),('port','Portugal y su red ultramarina'),('burg','Herencia borgoñona · Países Bajos'),('aust','Tierras austríacas, Bohemia y Hungría Real'),('imperial','Sacro Imperio · vínculo institucional')]
 if globalview:legend=[('hisp','Dominios europeos · colores por corona'),('escolon','Implantación colonial hispánica'),('ptcolon','Implantación colonial portuguesa'),('frontier','Trama · frontera, reclamación o penetración')]
 for j,(cat,label) in enumerate(legend):
  y=ly+47+j*27;fill='url(#frontier)' if cat=='frontier' else COL[cat];s +=[f'<rect x="{lx+20}" y="{y}" width="21" height="15" fill="{fill}" stroke="#9e9b88"/>',txt(lx+53,y+13,label,12 if not globalview else 13)]
 y=ly+47+len(legend)*27
 if globalview:s +=[f'<circle cx="{lx+30}" cy="{y+8}" r="4" fill="#3f827e" stroke="#344a48"/>',txt(lx+53,y+13,'Punto · enclave; círculo vacío · comercio / concesión',12),txt(lx+20,y+43,'Líneas y bandas · rutas y alcance comercial, no soberanía',12,'small')]
 else:s +=[txt(lx+20,y+18,'* Delimitación aproximada en las subdivisiones señaladas.',12,'small'),txt(lx+20,y+40,'Todos los colores dinásticos comparten soberano.',12,'small')]
 s+=['</g>',txt(48,1055 if not globalview else 1033,'La unión política no borra la diferencia entre gobernar, reclamar y comerciar',20),txt(48,1084 if not globalview else 1063,'Escenario: sucesión común desde 1555–1556, integración portuguesa desde 1580 y acuerdo que mantiene unidos los Países Bajos.',14,'small'),txt(48,1109 if not globalview else 1089,'El emperador mantiene su dignidad por elección: el resto del Sacro Imperio no se convierte en territorio directamente gobernado.',14,'small'),txt(48,1134 if not globalview else 1115,'La Monarquía conserva reinos, leyes y estamentos, con sucesión, diplomacia y defensa comunes. No se presupone un Estado unitario moderno.',14,'small')]
 if globalview:s +=[txt(48,1141,'África y Asia: los puntos no convierten sus hinterlands en colonias. Macao es un asentamiento autorizado; Nagasaki sigue siendo japonés.',14,'small'),txt(48,1167,'Las zonas americanas muestran implantación generalizada y fronteras abiertas. No son las fronteras de los países ni el imperio del siglo XVIII.',14,'small')]
 else:s +=[txt(48,1159,'Hungría otomana y Transilvania quedan fuera. Génova conserva su independencia; el corredor terrestre no implica anexar todos sus territorios.',14,'small')]
 s +=[txt(48,1215,'Base: Historical Basemaps · André Ourednik y colaboradores · 1600; capas posteriores solo para aproximar subdivisiones europeas.',12,'small'),txt(48,1240,'Proyección '+('Equal Earth · rutas esquemáticas' if globalview else 'Lambert cónica conforme · contorno imperial generalizado')+' · Fuentes, supuestos y fichas en la versión interactiva.',12,'small'),txt(48,1265,'Escenario contrafactual de elaboración propia · 5 de noviembre de 2026',12,'small'),'</svg>']
 return ''.join(s)
for key,glob in [('europa',False),('mundo',True)]: (ROOT/f'carlos_unificado_{key}.svg').write_text(render(glob),encoding='utf-8')
data=[{k:v for k,v in r.items() if k!='g'} for r in regions]
portdata=[dict(name=n,lon=x,lat=y,cat=c,note=t) for n,x,y,c,t in ports]
context='''<h1>La herencia de Carlos y la Unión Ibérica, hacia 1600</h1><p><b>La divergencia:</b> se evita la separación definitiva de las ramas hispánica y austríaca. Un pacto sucesorio y político vincula los reinos peninsulares, los dominios borgoñones y las tierras habsbúrgicas centroeuropeas. La incorporación portuguesa de 1580 se mantiene y se integra en esa estructura común.</p><p>No basta con cambiar el testamento de Carlos: Fernando ya había recibido el gobierno de las tierras austríacas en 1521–1522 y adquirió las coronas de Bohemia y Hungría en 1526. El escenario necesita un acuerdo con su rama y con los estamentos de esos reinos. Tampoco transforma por sí solo el cargo imperial, que sigue siendo electivo: se supone que la dinastía común conserva el apoyo de los electores.</p><h2>Qué significa «unificado»</h2><p>Una misma sucesión, una política exterior y una coordinación de defensa comunes, reforzadas por consejos compartidos. Se mantienen las leyes, instituciones y derechos territoriales de cada reino. Los colores distinguen procedencias y jurisdicciones, no países independientes. El botón de color único permite ver el conjunto dinástico como una sola unidad política. No se afirma que una monarquía tan extensa pudiera gobernarse sin conflictos.</p><h2>Dos hipótesis adicionales</h2><p><b>Países Bajos:</b> se supone un acuerdo religioso y fiscal que evita la ruptura permanente de las provincias del norte. En la historia real abjuraron de Felipe II en 1581; su continuidad aquí no deriva automáticamente del pacto sucesorio.</p><p><b>Portugal:</b> la unión de coronas fue real desde 1580. Lo contrafactual es su integración duradera con la rama austríaca y su permanencia futura; una vista de 1600, por sí sola, no prueba que no vaya a romperse en 1640. Tampoco se atribuyen a Carlos, fallecido en 1558, conquistas o decisiones de sus sucesores.</p><h2>Europa: títulos y territorios</h2><p>Austria, Bohemia y la parte habsbúrgica de Hungría se incorporan al pacto común. No se colorea como propia toda la Hungría histórica: el espacio otomano y Transilvania permanecen fuera. El Franco Condado se distingue del Ducado de Borgoña, que sigue siendo francés. Milán, Nápoles, Sicilia y Cerdeña son dominios de la Monarquía; Venecia, el Papado y Génova conservan sus gobiernos. La asociación financiera con Génova no equivale a soberanía territorial.</p><p>El área beige imperial representa una relación constitucional con el emperador, no control homogéneo ni una alianza militar garantizada. La línea imperial es una generalización continental; no reproduce todos los enclaves ni el complejo estatuto de cada feudo italiano o de la Confederación Suiza.</p><h2>Mundo: espacios con distintos grados de presencia</h2><p>Las superficies coloniales americanas muestran núcleos, corredores y franjas costeras, con límites indicativos. La trama marca fronteras abiertas y horizontes jurisdiccionales. Brasil no ocupa sus límites modernos; el Amazonas y las sociedades indígenas no se convierten automáticamente en dominio efectivo. En los Andes se representa implantación española en lugar de conservar la etiqueta anacrónica «Imperio inca» que contiene la base original de 1600.</p><p>En África y Asia prevalece una red de enclaves, ciudades fortificadas y acuerdos locales. Los símbolos tienen tamaño gráfico, no superficie territorial real. Macao aparece como asentamiento autorizado bajo soberanía china; Nagasaki como relación comercial con Japón. Las rutas expresan conexiones y alcance comercial compartido con mercaderes y Estados locales, no mares poseídos ni monopolios absolutos. Los corredores del Pacífico se separan en el borde del mapa para evitar una línea ficticia que cruce Eurasia.</p><h2>Método y límites</h2><p>Cartografía de Historical Basemaps de 1600, con correcciones y recortes explícitos. Las subdivisiones austríacas, bohemias y húngaras se aproximan con geometrías de 1938 y 1994: no son reconstrucciones catastrales del año 1600. Los polígonos coloniales y las tramas se han construido como esquemas geográficos, no como tratados de límites. Los mapas no incorporan anacrónicamente todas las conquistas ibéricas posteriores. La capa neutral contiene generalizaciones y posibles errores del conjunto original, por lo que no debe usarse para deducir cada frontera ajena a la Monarquía.</p>'''
style='''body{margin:0;background:#f6f1e6;color:#303b3b;font:16px/1.65 system-ui}nav{position:sticky;top:0;z-index:3;background:#393b35;color:#fff8e8;padding:13px 22px;display:flex;gap:12px;flex-wrap:wrap;align-items:center}button,nav a{border:1px solid #b6b19d;border-radius:5px;padding:7px 12px;font:14px system-ui;cursor:pointer;background:#faf5e8;color:#3f443c;text-decoration:none}button.active{background:#9e4253;color:white}button:focus-visible,a:focus-visible{outline:3px solid #29a2a5}.view{display:none;overflow:auto}.view.active{display:block}svg{width:100%;height:auto;min-width:1050px;display:block}#detail{padding:20px 28px;background:#fffbf3;border-block:1px solid #d2cbb7;min-height:105px}article{max-width:1040px;margin:auto;padding:30px}article a{color:#8b3e50}h1{font:32px Georgia}li{margin:10px 0}.smalltag{font-size:13px;color:#75715e}'''
page='<!doctype html><html lang="es"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>La monarquía de Carlos unificada · Europa y mundo</title><style>'+style+'</style><nav><b>Atlas · 1600 alternativo</b><button id="europe" class="active">Europa</button><button id="world">Mundo</button><button id="uniform">Color único / Coronas</button><button id="routes">Rutas</button><button id="frontiers">Fronteras coloniales</button><button id="zoom">Ampliar</button><button id="save">Descargar SVG</button><a id="png" href="carlos_unificado_europa.png">PNG</a><a href="#contexto">Supuestos y fuentes</a></nav><main><div id="europa" class="view active">'+render(False)+'</div><div id="mundo" class="view">'+render(True)+'</div><section id="detail" aria-live="polite">Pulsa un territorio o un punto para consultar su relación con la Monarquía. Los colores de cada corona comparten soberano.</section><article id="contexto">'+context+'<h2>Fuentes</h2><ul>'+''.join(f'<li><a href="{u}">{esc(t)}</a></li>' for t,u in sources)+'</ul></article></main><script>const regions='+json.dumps(data,ensure_ascii=False)+';const ports='+json.dumps(portdata,ensure_ascii=False)+''';let current='europa';function show(view){current=view;document.querySelectorAll('.view').forEach(e=>e.classList.toggle('active',e.id===view));document.getElementById('europe').classList.toggle('active',view==='europa');document.getElementById('world').classList.toggle('active',view==='mundo');document.getElementById('png').href='carlos_unificado_'+view+'.png'}document.getElementById('europe').onclick=()=>show('europa');document.getElementById('world').onclick=()=>show('mundo');document.getElementById('uniform').onclick=()=>document.body.classList.toggle('uniform');let routes=true,frontiers=true;document.getElementById('routes').onclick=()=>{routes=!routes;document.querySelectorAll('.route-layer').forEach(e=>e.style.display=routes?'':'none')};document.getElementById('frontiers').onclick=()=>{frontiers=!frontiers;document.querySelectorAll('.frontier-layer').forEach(e=>e.style.display=frontiers?'':'none')};document.getElementById('zoom').onclick=()=>{const s=document.querySelector('#'+current+' svg');s.style.width=s.style.width==='170%'?'100%':'170%'};function select(p){const r=(p.dataset.type==='port'?ports:regions)[p.dataset.i],e=document.getElementById('detail');e.replaceChildren();const b=document.createElement('b');b.textContent=r.name;const t=document.createElement('div');t.className='smalltag';t.textContent=p.dataset.type==='port'?'Punto de presencia o conexión · consultar su estatuto':(r.unified?'Dentro de la monarquía común':'Fuera del dominio dinástico directo')+(r.approx?' · Contorno aproximado':'');e.append(b,t,document.createTextNode(r.note))}document.querySelectorAll('[data-type]').forEach(p=>{p.onclick=()=>select(p);p.onkeydown=e=>{if(e.key==='Enter'||e.key===' '){e.preventDefault();select(p)}}});document.getElementById('save').onclick=()=>{const s=document.querySelector('#'+current+' svg').cloneNode(true);s.style.width='';if(document.body.classList.contains('uniform'))s.querySelectorAll('.unified').forEach(e=>e.setAttribute('fill','#9e4253'));const a=document.createElement('a');a.href=URL.createObjectURL(new Blob([new XMLSerializer().serializeToString(s)],{type:'image/svg+xml'}));a.download='carlos_unificado_'+current+'.svg';a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000)};</script></html>'''
# Evitar IDs de clip compartidos entre las dos vistas del mismo documento.
start=page.index('<div id="mundo"');end=page.index('</div><section id="detail"',start)
page=page[:start]+page[start:end].replace('id="mapclip"','id="worldclip"').replace('url(#mapclip)','url(#worldclip)').replace('id="frontier"','id="worldfrontier"').replace('url(#frontier)','url(#worldfrontier)')+page[end:]
(ROOT/'atlas_carlos_unificado.html').write_text(page,encoding='utf-8')
(ROOT/'FUENTES_Y_SUPUESTOS.md').write_text('# Monarquía unificada · 1600 alternativo\n\nSucesión común hispano-austríaca, Unión Ibérica y conservación de los Países Bajos mediante acuerdo. No es un mapa histórico real.\n\n'+ '\n'.join(f'- [{t}]({u})' for t,u in sources)+'\n\nConsultar los supuestos y límites completos en el HTML. Geometrías coloniales y subdivisiones europeas aproximadas; los puertos no implican soberanía sobre el hinterland.\n',encoding='utf-8')
(ROOT/'datos/escenario.geojson').write_text(json.dumps({'type':'FeatureCollection','features':[{'type':'Feature','properties':{k:v for k,v in r.items() if k!='g'},'geometry':mapping(r['g'])} for r in regions if r['unified']]},ensure_ascii=False),encoding='utf-8')
(ROOT/'datos/puertos_y_rutas.json').write_text(json.dumps({'ports':portdata,'routes':[dict(name=n,coordinates=c,cat=k) for n,c,k in routes]},ensure_ascii=False,indent=2),encoding='utf-8')
print('Generadas dos vistas SVG, atlas HTML y datos;',len(ports),'puntos;',len(regions),'regiones')
